mapper.select:
select t.id,t.supplier_id,t.pork_report_id,t.pork_arrange_audit_id
from meattrade_track t
left join meattrade_pork_report pr
on t.pork_report_id = pr.id
left join meattrade_pork_arrange_audit paa
on t.pork_arrange_audit_id = paa.id


        and pr.code like concat("%",#{param.keyword},"%")

            or t.supplier_id in

                #{supplierId}




        and pr.status = #{param.porkReportStatus}


        and paa.audit_status = #{param.porkArrangeAuditStatus}


        and pr.report_time between #{param.period.begin} and #{param.period.end}

    and pr.tenant = #{param.tenant}
    and t.tenant = #{param.tenant}

order by pr.code desc
